rss.channel:
    {{ .Site.Title }} – {{ .Title }}
    {{ .Permalink }}
    Recent content {{ if ne  .Title  .Site.Title }}{{ with .Title }}in {{.}} {{ end }}{{ end }}on {{ .Site.Title }}
    Hugo -- gohugo.io{{ with partial "utils/hugo-compat/language-locale.html" .Site.Language }}
    {{.}}{{end}}{{ with .Site.Params.Author.email }}
    {{.}}{{ with $.Site.Params.Author.name }} ({{.}}){{end}}{{end}}{{ with .Site.Params.Author.email }}
    {{.}}{{ with $.Site.Params.Author.name }} ({{.}}){{end}}{{end}}{{ with .Site.Copyright }}
    {{.}}{{end}}{{ if not .Date.IsZero }}
    {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}{{ end }}
    {{ with .OutputFormats.Get "RSS" }}
	  {{ printf "" .Permalink .MediaType | safeHTML }}
    {{ end }}
    {{ if not $.Section }}
      {{ $sections := .Site.Params.rss.sections | default (slice "blog") }}
      {{ .Store.Set "rssPages" (first 50 (where $.Site.RegularPages "Type" "in" $sections )) }}
    {{ else }}
      {{ if $.Parent.IsHome }}
        {{ .Store.Set "rssPages" (first 50 (where $.Site.RegularPages "Type" $.Section )) }}
      {{ else }}
        {{ .Store.Set "rssPages" (first 50 $.Pages) }}
      {{ end }}
    {{ end }}
    {{ range (.Store.Get "rssPages")  }}


      {{ .Title }}
      {{ .Permalink }}
      {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
      {{ with .Site.Params.Author.email }}{{.}}{{ with $.Site.Params.Author.name }} ({{.}}){{end}}{{end}}
      {{ .Permalink }}

        {{ $img := (.Resources.ByType "image").GetMatch "*featured*" }}
        {{ with $img }}
        {{/* Hugo counts image/svg+xml as resource type "image", so ByType picks
          up a featured.svg and hands it to .Resize, which is raster-only and
          fails the build. Every other place the theme processes an image guards
          this - card.html, render-image.html, page-image.html, gallery-item.html
          and identity.html - and this was the one that did not.

          An SVG is passed through at its own size, which is what those other
          guards do. No width or height: .Width on a non-raster resource is not
          meaningful, and a feed reader that cannot render SVG ignores the
          element either way. */}}
        {{ if eq .MediaType.SubType "svg" }}
        {{ printf "<img src=\"%s\"/>" .Permalink | safeHTML }}
        {{ else }}
        {{ $img := .Resize "640x" }}
        {{ printf "<img src=\"%s\" width=\"%d\" height=\"%d\"/>" $img.Permalink $img.Width $img.Height | safeHTML }}
        {{ end }}
        {{ end }}
        {{ .Content | html }}


    {{ end }}
